    if contact_blend and not contact_length_budget:raise ValueError('Contact blend requires reserved common counts')
    if relocate_earlier and not station_relocation:raise ValueError('Earlier relocation requires station relocation')
    if centered and (not station_relocation or relocate_earlier):raise ValueError('Centered relocation requires its own station policy')
    if continuous and not centered:raise ValueError('Continuous relocation requires centered stations')
